import csv

# Read expenses.csv
with open('data/expenses.csv', newline='') as f:
    reader = csv.DictReader(f)
    travel_expenses = []
    for row in reader:
        if row['category'].strip() == 'Travel':
            # Filter by date range: 2026-01-01 to 2026-03-31 inclusive
            date = row['date'].strip()
            if date.startswith('2026-') and (date.startswith('2026-01') or date.startswith('2026-02') or date.startswith('2026-03')):
                try:
                    amount = float(row['amount'])
                    travel_expenses.append((row, amount))
                except ValueError:
                    pass

    print(f'Total travel expenses found: {len(travel_expenses)}')
    for row, amt in travel_expenses:
